"
TEMP_MODULE="/data/nh.ko"
echo "$MODULE_BASE64" | base64 -d > "$TEMP_MODULE"


ERROR_MSG=$(insmod "$TEMP_MODULE" 2>&1)
if [ $? -eq 0 ]; then
  echo -e "${COLOR_GREEN}→ 水原千鹤驱动刷入成功"
  rm -f "$TEMP_MODULE"
else
  echo -e "${COLOR_YELLOW}刷入失败，请重启手机后再试一次，确定不行再换其他脚本。${RESET_SEQ}"
  echo "3 秒后自动重启设备..."
  sleep 3
  reboot
  exit 1
fi